def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            if opp.get('budget', 0) >= budget:
                rich_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    units = max(1, int(supply / WATER_REQ))
    scarcity = 0
    if units <= 1:
        scarcity = 2
    elif units == 2:
        scarcity = 1

    top_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    desperation = 0
    if hp <= 2:
        desperation = 3
    elif hp <= 4 or no_water_days >= 1:
        desperation = 2
    elif hp <= 6:
        desperation = 1

    if desperation >= 3:
        bid = max(62.0, top_prev + 2.5)
        if scarcity == 2:
            bid = max(bid, 78.0)
        return float(min(budget, bid))

    if scarcity == 2:
        if desperation >= 2:
            bid = max(58.0, top_prev + 1.8)
        else:
            if top_prev >= 95:
                bid = 24.0
            elif top_prev >= 70:
                bid = 36.0
            else:
                bid = max(42.0, top_prev + 1.2)
        if urgent_opp >= 2:
            bid += 6.0
        return float(min(budget, bid))

    if scarcity == 1:
        if top_prev >= 100:
            bid = 20.0 if desperation == 0 else 48.0
        elif top_prev >= 75:
            bid = 26.0 if desperation == 0 else 52.0
        else:
            bid = max(28.0, avg_prev * 0.72 + 2.0)
        if desperation >= 2:
            bid += 8.0
        elif desperation == 1:
            bid += 4.0
        return float(min(budget, bid))

    bid = 18.0
    if top_prev > 0:
        if top_prev >= 100:
            bid = 14.0
        elif top_prev >= 80:
            bid = 16.0
        else:
            bid = max(18.0, min(32.0, top_prev * 0.55 + 1.0))

    if desperation >= 2:
        bid += 10.0
    elif desperation == 1:
        bid += 5.0

    if rich_opp >= 2 and top_prev < 60:
        bid += 2.0

    if day >= 8 and hp <= 5:
        bid = max(bid, 40.0)

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    # If no opponents alive, conserve budget
    if not alive_opponents:
        bid = DAILY_SALARY * 0.35
        if my_budget < bid:
            bid = my_budget
        return float(max(0.0, bid))

    # Read yesterday bids from previous_trace only
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply pressure: lower supply means more likely competition for water
    # Normalize to [0,1]
    if MAX_SUPPLY <= MIN_SUPPLY:
        supply_pressure = 0.5
    else:
        supply_pressure = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
        if supply_pressure < 0.0:
            supply_pressure = 0.0
        if supply_pressure > 1.0:
            supply_pressure = 1.0

    # Base bid: aim around a fraction of daily salary, adjusted by supply pressure
    base = DAILY_SALARY * (0.45 + 0.25 * supply_pressure)

    # If someone already bid very high yesterday, increment slightly to avoid losing
    # without going all-in.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # If I'm healthy, outbid slightly; if low hp, bid more aggressively
        if my_hp > 3.0:
            target = max(base, highest_prev_bid * 0.92)
        else:
            target = max(base, highest_prev_bid * 0.98)
    else:
        # Otherwise, bid just above the expected clearing pressure
        target = max(base, highest_prev_bid * 0.70 + 5.0)

    # Urgency from my own hp/no_water_days
    # If I've already gone several days without water, increase bid.
    if my_hp <= 2.5 or my_no_water_days >= 2:
        target *= 1.25
    elif my_hp >= 6.0 and my_no_water_days <= 0:
        target *= 0.85

    # Late-episode pressure: closer to day 10, more likely to need water
    if day >= 8:
        target *= 1.12

    # Budget safety: never exceed budget; keep some reserve
    # Reserve fraction increases when hp is low? Actually reserve decreases when low hp.
    if my_hp <= 2.5:
        reserve_frac = 0.05
    elif my_hp <= 4.0:
        reserve_frac = 0.10
    else:
        reserve_frac = 0.20

    max_affordable = max(0.0, my_budget * (1.0 - reserve_frac))
    bid = min(float(max_affordable), float(target))

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
